import { openSync, closeSync, readFileSync, mkdirSync, writeFileSync } from "node:fs"
import { createHash } from "node:crypto"
import { resolve } from "node:path"
import { runBuildProcess } from "/candidate-244/scripts/build-process.mjs"
import { actualTaskCacheEvents } from "/candidate-244/scripts/run-build-workflow-acceptance.mjs"
const root = "/candidate-244"
const label = process.argv[2]
if (!/^[a-z0-9-]+$/.test(label)) throw new Error("Invalid run label")
const directory = resolve(root, ".test-runs/build-evidence-reuse")
mkdirSync(directory, { recursive: true })
const logPath = resolve(directory, `${label}.log`)
const fd = openSync(logPath, "w")
const startedAt = new Date().toISOString()
const started = performance.now()
let failure
try {
  await runBuildProcess(process.execPath, [resolve(root, "scripts/build-product.mjs")], {
    cwd: root, env: { ...process.env, HAPSLAND_BUILD_PROFILE: "linux-arm64", TURBO_TELEMETRY_DISABLED: "1" },
    timeout: 240000, stdio: ["ignore", fd, fd]
  })
} catch (error) { failure = error.message }
finally { closeSync(fd) }
const seconds = (performance.now() - started) / 1000
const log = readFileSync(logPath)
const text = log.toString()
const result = {
  label, startedAt, deadlineSeconds: 240, seconds, success: !failure,
  ...(failure ? { error: failure } : {}),
  log: { path: logPath, sha256: createHash("sha256").update(log).digest("hex"), bytes: log.length },
  events: actualTaskCacheEvents(text),
  published: text.includes("Published product: fresh source, compiler, native and artifact evidence verified")
}
writeFileSync(resolve(directory, `${label}.json`), JSON.stringify(result, null, 2) + "\n")
console.log(JSON.stringify({ label, seconds, success: result.success, published: result.published,
  hits: result.events.filter(event => event.state === "hit").length,
  misses: result.events.filter(event => event.state === "miss").length,
  bypasses: result.events.filter(event => event.state === "bypass").length,
  ...(failure ? { error: failure } : {}) }))
if (failure) { console.error(text.slice(-6500)); process.exitCode = 1 }
